import { useState, useCallback } from 'react';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { Layout, theme } from '@atlantis/shared';
import { buildPollinationsUrl, enhancePrompt, getGroqKey } from './api';
import { loadGallery, prependGalleryItem, deleteGalleryItem, loadSettings, saveSettings } from './storage';
import type { GalleryItem, ImageSettings } from './storage';
import { PromptBar } from './components/PromptBar';
import { ImageDisplay } from './components/ImageDisplay';
import { Gallery } from './components/Gallery';

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
`;

const Content = styled.div`
  display: flex;
  flex-direction: column;
  gap: ${theme.spacing.lg};
  padding: ${theme.spacing.lg};
  height: 100%;
  overflow-y: auto;
  animation: ${fadeIn} 0.25s ease;
`;

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [prompt, setPrompt] = useState('');
  const [settings, setSettings] = useState<ImageSettings>(() => loadSettings());
  const [currentUrl, setCurrentUrl] = useState<string | null>(null);
  const [imageStatus, setImageStatus] = useState<'idle' | 'loading' | 'loaded' | 'error'>('idle');
  const [gallery, setGallery] = useState<GalleryItem[]>(() => loadGallery());
  const [enhancing, setEnhancing] = useState(false);
  const [currentSeed, setCurrentSeed] = useState(0);

  const groqKey = getGroqKey();
  const canEnhance = Boolean(groqKey);

  const handleSizeChange = (w: number, h: number) => {
    const next = { ...settings, width: w, height: h };
    setSettings(next);
    saveSettings(next);
  };

  const handleModelChange = (m: string) => {
    const next = { ...settings, model: m };
    setSettings(next);
    saveSettings(next);
  };

  const doGenerate = useCallback((p: string, seed: number) => {
    const url = buildPollinationsUrl({
      prompt: p,
      width: settings.width,
      height: settings.height,
      seed,
      model: settings.model,
    });
    setCurrentUrl(url);
    setCurrentSeed(seed);
    setImageStatus('loading');
  }, [settings]);

  const handleGenerate = () => {
    if (!prompt.trim()) return;
    const seed = Math.floor(Math.random() * 2 ** 31);
    doGenerate(prompt, seed);
  };

  const handleReroll = () => {
    if (!prompt.trim()) return;
    const seed = Math.floor(Math.random() * 2 ** 31);
    doGenerate(prompt, seed);
  };

  const handleRetry = () => {
    if (!prompt.trim()) return;
    doGenerate(prompt, currentSeed);
  };

  const handleImageLoaded = () => {
    setImageStatus('loaded');
    if (!currentUrl) return;
    const item: GalleryItem = {
      id: crypto.randomUUID(),
      prompt,
      url: currentUrl,
      seed: currentSeed,
      width: settings.width,
      height: settings.height,
      model: settings.model,
      generatedAt: Date.now(),
    };
    setGallery(prependGalleryItem(item));
  };

  const handleImageError = () => {
    setImageStatus('error');
  };

  const handleEnhance = async () => {
    if (!canEnhance || !prompt.trim() || enhancing) return;
    setEnhancing(true);
    try {
      const enhanced = await enhancePrompt(groqKey, prompt);
      setPrompt(enhanced);
    } catch {
      // silently fail — user still has original prompt
    } finally {
      setEnhancing(false);
    }
  };

  const handleGallerySelect = (item: GalleryItem) => {
    setPrompt(item.prompt);
    setCurrentUrl(item.url);
    setCurrentSeed(item.seed);
    setImageStatus('loaded');
  };

  const handleGalleryDelete = (id: string) => {
    setGallery(deleteGalleryItem(id));
  };

  return (
    <Layout title="Image Gen" sidebar={null} topBarRight={topBarRight}>
      <Content>
        <PromptBar
          prompt={prompt}
          onPromptChange={setPrompt}
          width={settings.width}
          height={settings.height}
          model={settings.model}
          onSizeChange={handleSizeChange}
          onModelChange={handleModelChange}
          onGenerate={handleGenerate}
          onEnhance={handleEnhance}
          generating={imageStatus === 'loading'}
          enhancing={enhancing}
          canEnhance={canEnhance}
        />

        <ImageDisplay
          url={currentUrl}
          status={imageStatus}
          width={settings.width}
          height={settings.height}
          onLoad={handleImageLoaded}
          onError={handleImageError}
          onReroll={handleReroll}
          onRetry={handleRetry}
        />

        <Gallery
          items={gallery}
          onSelect={handleGallerySelect}
          onDelete={handleGalleryDelete}
        />
      </Content>
    </Layout>
  );
}
